theorem submultiplicativeHull_one {φ : ℝ → ℝ}
    (hφ : ∀ x, 1 ≤ x → 1 ≤ φ x) (hφone : φ 1 ≤ 1) : submultiplicativeHull φ 1 = 1 :=
  le_antisymm ((submultiplicativeHull_le hφ le_rfl).trans hφone) (one_le_submultiplicativeHull hφ 1)

